// Measures bundle size like test/bench/bundle.test.ts, optionally replacing two files with their HEAD version.
import { createRequire } from "node:module";
import { execFileSync } from "node:child_process";
import zlib from "node:zlib";

const repo = "C:/dev/runs/r3a7c2058ca";
const require = createRequire(`${repo}/package.json`);
const { build } = require("esbuild");

const useHead = process.argv[2] === "head";
const headFiles = new Set(["src/error.ts", "src/response.ts"]);

const entries = {
  H3: `import { H3 } from "${repo}/src/index.ts"; new H3();`,
  H3Core: `import { H3Core } from "${repo}/src/index.ts"; new H3Core();`,
  defineHandler: `import { defineHandler } from "${repo}/src/index.ts"; defineHandler({});`,
};

for (const [name, code] of Object.entries(entries)) {
  const result = await build({
    bundle: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logLevel: "silent",
    stdin: { contents: code, resolveDir: repo, sourcefile: "index.mjs", loader: "js" },
    plugins: [
      {
        name: "head-files",
        setup(b) {
          if (!useHead) return;
          b.onLoad({ filter: /src[\\/](error|response)\.ts$/ }, (args) => {
            const rel = args.path.replace(/\\/g, "/").split("/src/")[1];
            const contents = execFileSync("git", ["show", `HEAD:src/${rel}`], {
              cwd: repo,
              encoding: "utf8",
            });
            return { contents, loader: "ts", resolveDir: repo + "/src" };
          });
        },
      },
    ],
  });
  const out = result.outputFiles[0].contents;
  const gzip = zlib.gzipSync(out).length;
  console.log(`${useHead ? "HEAD" : "WORKTREE"} ${name}: ${out.length} (gzip: ${gzip})`);
}

